  const [savedState,setSavedState]=useState('Loading'),[draft,setDraft]=useState(null),[newTag,setNewTag]=useState({type:'category',name:'',color:palette[0]}),[menuOpen,setMenuOpen]=useState(false),[installPrompt,setInstallPrompt]=useState(null),[editLists,setEditLists]=useState({ locations:false, tags:false }),[selectedItems,setSelectedItems]=useState([]),[bulkLocation,setBulkLocation]=useState({floorId:'',shelfId:'',levelId:''}),[backups,setBackups]=useState([]);
  useEffect(()=>{ loadState().then(({data,source})=>{ setState(data); setSelectedId(data.items[0]?.id||''); const savedUser=sessionStorage.getItem('home-inventory-current-user'); if(savedUser){ const u=data.users.find((x)=>x.id===savedUser); if(u) setCurrentUser(u); } setSavedState(source); setLoaded(true); }); },[]);
