  useEffect(()=>{ const h=(e)=>{ e.preventDefault(); setInstallPrompt(e); }; window.addEventListener('beforeinstallprompt',h); return()=>window.removeEventListener('beforeinstallprompt',h); },[]);
  const currentProfile=currentUser?userById(state.users,currentUser.id):null; const theme=themes.find((t)=>t.id===currentProfile?.theme)||themes[0]; const schemeList=themeSchemes[theme.id]||[]; const scheme=schemeList.find((x)=>x[0]===(currentProfile?.scheme||schemeList[0]?.[0]))||schemeList[0]||['default',theme.accent,theme.accent2]; const selected=state.items.find((i)=>i.id===selectedId) || state.items.find((i)=>!currentProfile||canView(i,currentProfile)) || null;
