  const refreshBackups=async()=>setBackups(await loadBackups());
  const rollbackBackup=async(id)=>{ await restoreBackup(id); const {data,source}=await loadState(); setState(data); setSelectedId(data.items[0]?.id||''); await refreshBackups(); setSavedState(`Rolled back · ${source}`); };
  const visibleItems=useMemo(()=> currentProfile ? state.items.filter((i)=>canView(i,currentProfile)) : state.items, [state.items,currentProfile]);
  useEffect(()=>{ if(visibleItems.length && !visibleItems.some((i)=>i.id===selectedId)) setSelectedId(visibleItems[0].id); if(!visibleItems.length && selectedId) setSelectedId(''); },[visibleItems,selectedId]);
  const filtered=useMemo(()=>visibleItems.filter((item)=>{ const q=query.trim().toLowerCase(); const hay=[item.tag,item.title,item.content,byId(state.categories,item.categoryId).name,byId(state.seasons,item.seasonId).name,userName(state.users,item.ownerId),locationLine(item.location,state),item.location.containerName,item.location.boxSpot,item.location.notes].join(' ').toLowerCase(); return (ownerFilter==='all'||item.ownerId===ownerFilter)&&(categoryFilter==='all'||item.categoryId===categoryFilter)&&(seasonFilter==='all'||item.seasonId===seasonFilter)&&(floorFilter==='all'||item.location.floorId===floorFilter)&&(shelfFilter==='all'||item.location.shelfId===shelfFilter)&&(levelFilter==='all'||item.location.levelId===levelFilter)&&(!q||hay.includes(q)); }),[visibleItems,state,ownerFilter,categoryFilter,seasonFilter,floorFilter,shelfFilter,levelFilter,query]);
  const groups=useMemo(()=>{ const m=new Map(); visibleItems.forEach((item)=>{ const key=`${item.location.floorId}|${item.location.shelfId}|${item.location.levelId}`; if(!m.has(key)) m.set(key,{key,location:item.location,items:[]}); m.get(key).items.push(item); }); return Array.from(m.values()); },[visibleItems]);
  const startAdd=()=>{ const max=state.items.reduce((h,i)=>Math.max(h,Number(i.tag)||0),0); const next=emptyItem(state,currentProfile.id); next.tag=String(max+1).padStart(3,'0'); setDraft(next); setActiveTab('add'); };
