  const saveDraft=()=>{ if(!draft.title.trim()) return setSavedState('Add an item name before saving'); const exists=state.items.some((i)=>i.id===draft.id); const next={...draft,title:draft.title.trim(),color:draft.color||userById(state.users,draft.ownerId).accent,tag:String(draft.tag||'001').padStart(3,'0'),lastEdited:today(),history:exists?draft.history:[{action:'Created',person:currentProfile.displayName,date:today(),note:'Item added from phone dashboard.'}]}; const items=exists?state.items.map((i)=>i.id===draft.id?next:i):[next,...state.items]; persist({...state,items},exists?'Item saved':`Tag ${next.tag} added`); setSelectedId(next.id); setDraft(null); setActiveTab('browse'); };
  const deleteDraft=()=>{ if(!draft) return; if(!state.items.some((i)=>i.id===draft.id)){ setDraft(null); setActiveTab('browse'); return; } if(!window.confirm(`Delete ${draft.title||'this item'}?`)) return; const items=state.items.filter((i)=>i.id!==draft.id); persist({...state,items},'Item deleted'); setSelectedId(items[0]?.id||''); setDraft(null); setActiveTab('browse'); };
  const changeStatus=(item=selected)=>{ if(!item) return; if(item.locked && !canTake(item,currentProfile)) return setSavedState('Request approval before taking this locked item'); const nextStatus=item.status==='In'?'Out':'In'; const note=window.prompt(`Note for ${nextStatus==='In'?'adding back':'taking out'} ${item.title}:`, nextStatus==='In'?'Returned to storage.':'Taking out for use.') || ''; const entry={action:nextStatus==='In'?'Returned':'Taken',person:currentProfile.displayName,userId:currentProfile.id,date:today(),note}; const items=state.items.map((i)=>i.id===item.id?{...i,status:nextStatus,history:[entry,...(i.history||[])],lastEdited:today()}:i); persist({...state,items},`${item.title} marked ${nextStatus}`); };
  const requestItem=(item=selected)=>{ if(!item) return; const note=window.prompt(`Request to take ${item.title}. Add a note for ${userName(state.users,item.ownerId)}:`, 'Can I take this out?') || ''; const req={id:makeId('request'),userId:currentProfile.id,userName:currentProfile.displayName,status:'pending',note,date:today()}; persist({...state,items:state.items.map((i)=>i.id===item.id?{...i,requests:[req,...(i.requests||[])]}:i)},'Request sent'); };
  const decideRequest=(item,req,status)=>persist({...state,items:state.items.map((i)=>i.id===item.id?{...i,requests:(i.requests||[]).map((r)=>r.id===req.id?{...r,status,decidedBy:currentProfile.id,decidedDate:today()}:r)}:i)},`Request ${status}`);
  const toggleBulkItem=(id)=>setSelectedItems((ids)=>ids.includes(id)?ids.filter((x)=>x!==id):[...ids,id]);
  const selectVisibleItems=()=>setSelectedItems(filtered.map((i)=>i.id));
  const clearBulkItems=()=>setSelectedItems([]);
  const moveSelectedItems=()=>{ if(!selectedItems.length) return setSavedState('Select items to move first'); const patch={}; if(bulkLocation.floorId) patch.floorId=bulkLocation.floorId; if(bulkLocation.shelfId) patch.shelfId=bulkLocation.shelfId; if(bulkLocation.levelId) patch.levelId=bulkLocation.levelId; if(!Object.keys(patch).length) return setSavedState('Choose a new floor, shelf, or level'); const items=state.items.map((item)=>selectedItems.includes(item.id)?{...item,location:{...item.location,...patch},lastEdited:today(),history:[{action:'Moved',person:currentProfile.displayName,userId:currentProfile.id,date:today(),note:`Bulk moved ${Object.keys(patch).join(', ')}`},...(item.history||[])]}:item); persist({...state,items},`${selectedItems.length} items moved`); setSelectedItems([]); };
  const copyEndpoint=async(item=selected)=>{ try{ await navigator.clipboard.writeText(endpointFor(item.tag)); setSavedState(`Copied tag ${item.tag} URL`); }catch{ setSavedState(endpointFor(item.tag)); } };
  const quickFilter=(patch)=>{ if('ownerFilter'in patch)setOwnerFilter(patch.ownerFilter); if('categoryFilter'in patch)setCategoryFilter(patch.categoryFilter); if('seasonFilter'in patch)setSeasonFilter(patch.seasonFilter); if('floorFilter'in patch)setFloorFilter(patch.floorFilter); if('shelfFilter'in patch)setShelfFilter(patch.shelfFilter); if('levelFilter'in patch)setLevelFilter(patch.levelFilter); setActiveTab('browse'); };
  const listKey=(type)=>({category:'categories',season:'seasons',floor:'floors',shelf:'shelves',level:'levels'}[type]);
  const addTag=()=>{ const clean=titleCase(newTag.name); if(!clean) return; const entry={id:slug(clean),name:clean,color:newTag.color}; const key=listKey(newTag.type); if(state[key]?.some((x)=>x.id===entry.id)) return setSavedState(`${clean} already exists`); persist({...state,[key]:[...state[key],entry]},`${clean} added`); setNewTag({...newTag,name:''}); };
  const deleteListEntry=(type,id)=>{ const key=listKey(type); const used=state.items.some((i)=>type==='category'?i.categoryId===id:type==='season'?i.seasonId===id:type==='floor'?i.location.floorId===id:type==='shelf'?i.location.shelfId===id:i.location.levelId===id); if(used) return setSavedState('Move items off this tag before deleting it'); persist({...state,[key]:state[key].filter((e)=>e.id!==id)},'Tag deleted'); };
  const updateListEntry=(type,id,patch)=>{ const key=listKey(type); persist({...state,[key]:state[key].map((e)=>e.id===id?{...e,...patch}:e)},'Tag updated'); };
