  if(!loaded) return <main className="loginPage"><section className="loginPanel"><h1>Home Inventory</h1><p>Loading inventory...</p></section></main>;
  if(window.location.pathname.startsWith('/tag/') || window.location.pathname.startsWith('/shelf/') || window.location.pathname.startsWith('/box/')) return <NfcPage state={state}/>;
  if(!currentProfile) return <Login users={state.users} onLogin={setCurrentUser} onUpdateUsers={updateUsers}/>;
  return <main className={`appShell mode-${currentProfile.mode||'light'} theme-${theme.id}`} style={{'--green':scheme[1]||theme.accent,'--green-dark':scheme[1]||theme.accent,'--theme2':scheme[2]||theme.accent2,'--app-font':theme.font}}><header className="topbar"><div className="brand"><span className="brandMark"><Icon name="box"/></span><div><h1>Home Inventory</h1><p>Find, add, scan, and organize family belongings</p></div></div><div className="topActions"><span className="saveState">{savedState}</span><div className="userMenu"><button className="avatarButton" onClick={()=>setMenuOpen(!menuOpen)}><Avatar user={currentProfile}/><span>{currentProfile.displayName}</span></button>{menuOpen&&<div className="menuPanel"><button onClick={()=>{setActiveTab('settings');setMenuOpen(false);}}><Icon name="gear"/> Settings</button><button onClick={()=>setCurrentUser(null)}><Icon name="user"/> Log out</button></div>}</div><button className="primaryButton" onClick={startAdd}><Icon name="plus"/> Add Item</button></div></header><nav className="tabbar" aria-label="Inventory sections">{tabs.map((tab)=><button key={tab.id} className={activeTab===tab.id?'active':''} onClick={()=>setActiveTab(tab.id)}>{tab.label}</button>)}</nav>{!state.onboardingDone&&<section className="onboarding"><div><p className="eyebrow">Easy setup</p><h2>Start with one shelf and one item.</h2><p>Settings live under your user icon. Tags and shelves stay view-safe until you tap Edit.</p></div><button className="secondaryButton" onClick={markOnboardingDone}>Hide guide</button></section>}{activeTab==='home'&&<HomeTab state={state} currentProfile={currentProfile} visibleItems={visibleItems} quickFilter={quickFilter} startAdd={startAdd}/>} {activeTab==='add'&&<EditTab draft={draft} setDraft={setDraft} state={state} saveDraft={saveDraft} deleteDraft={deleteDraft} startAdd={startAdd} readPhoto={readPhoto}/>} {activeTab==='browse'&&<BrowseTab state={state} filtered={filtered} selected={selected} currentProfile={currentProfile} setSelectedId={setSelectedId} startEdit={startEdit} changeStatus={changeStatus} requestItem={requestItem} decideRequest={decideRequest} copyEndpoint={copyEndpoint} selectedItems={selectedItems} toggleBulkItem={toggleBulkItem} selectVisibleItems={selectVisibleItems} clearBulkItems={clearBulkItems} bulkLocation={bulkLocation} setBulkLocation={setBulkLocation} moveSelectedItems={moveSelectedItems} filters={{ownerFilter,categoryFilter,seasonFilter,floorFilter,shelfFilter,levelFilter,query}} setters={{setOwnerFilter,setCategoryFilter,setSeasonFilter,setFloorFilter,setShelfFilter,setLevelFilter,setQuery}}/>} {activeTab==='locations'&&<LocationsTab groups={groups} state={state} quickFilter={quickFilter} startEdit={startEdit} addTag={addTag} newTag={newTag} setNewTag={setNewTag} deleteListEntry={deleteListEntry} updateListEntry={updateListEntry} editing={editLists.locations} setEditing={(v)=>setEditLists({...editLists,locations:v})}/>} {activeTab==='categories'&&<TagsTab state={state} quickFilter={quickFilter} addTag={addTag} newTag={newTag} setNewTag={setNewTag} deleteListEntry={deleteListEntry} updateListEntry={updateListEntry} editing={editLists.tags} setEditing={(v)=>setEditLists({...editLists,tags:v})}/>} {activeTab==='settings'&&<MySettings currentProfile={currentProfile} updateCurrentUser={updateCurrentUser} readPhoto={readPhoto} installApp={installApp} reopenGuide={reopenGuide} backups={backups} refreshBackups={refreshBackups} rollbackBackup={rollbackBackup} schemeList={schemeList}/>}</main>;
