function HomeTab({state,currentProfile,visibleItems,quickFilter,startAdd}){ return <section className="homeGrid"><div className="heroPanel"><p className="eyebrow">Welcome, {currentProfile.displayName}</p><h2>What do you want to find?</h2><p>Locked items can require approval before another person takes them. Private locked items are hidden from other users.</p><div className="heroActions"><button className="primaryButton big" onClick={startAdd}><Icon name="plus"/> Add a new item</button><button className="secondaryButton big" onClick={()=>quickFilter({ownerFilter:currentProfile.id})}>Show my items</button></div></div><StatCard label="Visible items" value={visibleItems.length}/><StatCard label="My items" value={state.items.filter((i)=>i.ownerId===currentProfile.id).length}/><StatCard label="Locked" value={state.items.filter((i)=>i.locked).length}/><StatCard label="Requests" value={state.items.filter((i)=>i.ownerId===currentProfile.id).flatMap((i)=>i.requests||[]).filter((r)=>r.status==='pending').length}/><QuickPanel title="People">{state.users.map((u)=><button key={u.id} onClick={()=>quickFilter({ownerFilter:u.id})}><Avatar user={u}/> {u.displayName}<strong>{visibleItems.filter((i)=>i.ownerId===u.id).length}</strong></button>)}</QuickPanel><QuickPanel title="Seasonal tags">{state.seasons.filter((s)=>s.id!=='none').slice(0,8).map((tag)=><button key={tag.id} onClick={()=>quickFilter({seasonFilter:tag.id})}><Dot color={tag.color}/> {tag.name}<strong>{visibleItems.filter((i)=>i.seasonId===tag.id).length}</strong></button>)}</QuickPanel></section>; }
function StatCard({label,value}){ return <article className="statCard"><strong>{value}</strong><span>{label}</span></article>; }
function QuickPanel({title,children}){ return <section className="quickPanel"><h3>{title}</h3><div className="chipGrid">{children}</div></section>; }
function EditTab({draft,setDraft,state,saveDraft,deleteDraft,startAdd,readPhoto}){ if(!draft) return <section className="emptyPanel"><h2>Add or edit an item</h2><p>Use the big button below to make a new NFC item card, or open Browse and edit an existing item.</p><button className="primaryButton big" onClick={startAdd}><Icon name="plus"/> Add item</button></section>; const update=(p)=>setDraft({...draft,...p}); const updateLocation=(p)=>setDraft({...draft,location:{...draft.location,...p}}); const ownerAccent=userById(state.users,draft.ownerId).accent||'#16766f'; return <section className="editLayout"><div className="editPanel"><p className="eyebrow">Step 1</p><h2>Name, owner, and lock</h2><label>Item name<input value={draft.title} onChange={(e)=>update({title:e.target.value})} placeholder="Blue tool box"/></label><label>What is inside?<textarea value={draft.content} onChange={(e)=>update({content:e.target.value})}/></label><div className="fieldGrid"><label>Person<select value={draft.ownerId} onChange={(e)=>update({ownerId:e.target.value,color:userById(state.users,e.target.value).accent})}>{state.users.map((u)=><option key={u.id} value={u.id}>{u.displayName}</option>)}</select></label><label>Item color<input type="color" value={draft.color||ownerAccent} onChange={(e)=>update({color:e.target.value})}/></label></div><div className="checkGrid"><label><input type="checkbox" checked={!!draft.locked} onChange={(e)=>update({locked:e.target.checked})}/> Lock item: others request before taking</label><label><input type="checkbox" checked={!!draft.hiddenFromOthers} onChange={(e)=>update({hiddenFromOthers:e.target.checked})}/> Hide from other users</label></div><div className="fieldGrid"><label>Category<select value={draft.categoryId} onChange={(e)=>update({categoryId:e.target.value})}>{state.categories.map((c)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Season / holiday<select value={draft.seasonId||'none'} onChange={(e)=>update({seasonId:e.target.value})}>{state.seasons.map((s)=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label></div><div className="fieldGrid"><label>Tag number<input value={draft.tag} onChange={(e)=>update({tag:e.target.value.replace(/\D/g,'').slice(0,4)})}/></label><label>Status<select value={draft.status} onChange={(e)=>update({status:e.target.value})}><option>In</option><option>Out</option></select></label></div></div><div className="editPanel"><p className="eyebrow">Step 2</p><h2>Show where it lives</h2><div className="fieldGrid"><label>Floor / room<select value={draft.location.floorId} onChange={(e)=>updateLocation({floorId:e.target.value})}>{state.floors.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Shelf<select value={draft.location.shelfId} onChange={(e)=>updateLocation({shelfId:e.target.value})}>{state.shelves.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><div className="fieldGrid"><label>Shelf level<select value={draft.location.levelId} onChange={(e)=>updateLocation({levelId:e.target.value})}>{state.levels.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Side<select value={draft.location.shelfZone} onChange={(e)=>updateLocation({shelfZone:e.target.value})}>{shelfZones.map((z)=><option key={z}>{z}</option>)}</select></label></div><div className="fieldGrid"><label>Container type<select value={draft.location.containerType} onChange={(e)=>updateLocation({containerType:e.target.value})}>{containerTypes.map((t)=><option key={t}>{t}</option>)}</select></label><label>Box/bin name<input value={draft.location.containerName} onChange={(e)=>updateLocation({containerName:e.target.value})}/></label></div><div className="fieldGrid"><label>Box NFC tag<input value={draft.location.boxTag||draft.tag} onChange={(e)=>updateLocation({boxTag:e.target.value.replace(/\D/g,'').slice(0,4)})} placeholder="023"/></label><label>Spot and notes<input value={draft.location.boxSpot} onChange={(e)=>updateLocation({boxSpot:e.target.value})}/></label></div><label>Extra location notes<input value={draft.location.notes} onChange={(e)=>updateLocation({notes:e.target.value})}/></label></div><div className="editPanel"><p className="eyebrow">Step 3</p><h2>Add photos and save</h2><div className="photoGrid"><label className="photoInput"><PhotoBox src={draft.photo} label="Item photo"/><input type="file" accept="image/*" capture="environment" onChange={(e)=>readPhoto(e.target.files?.[0],(photo)=>update({photo}))}/></label><label className="photoInput"><PhotoBox src={draft.location.photo} label="Shelf photo"/><input type="file" accept="image/*" capture="environment" onChange={(e)=>readPhoto(e.target.files?.[0],(photo)=>updateLocation({photo}))}/></label></div><div className="endpointPreview"><span>NFC URLs</span><code>Item: {endpointFor(draft.tag||'001')}</code><code>Shelf: {shelfUrl(byId(state.shelves,draft.location.shelfId))}</code><code>Level: {levelUrl(byId(state.shelves,draft.location.shelfId),byId(state.levels,draft.location.levelId))}</code><code>Box: /box/{tagNumber(draft.location.boxTag||draft.tag)}</code></div><div className="saveRow"><button className="primaryButton big" onClick={saveDraft}><Icon name="save"/> Save item</button><button className="dangerButton big" onClick={deleteDraft}><Icon name="trash"/> Delete</button></div></div></section>; }
function BrowseTab({state,filtered,selected,currentProfile,setSelectedId,startEdit,changeStatus,requestItem,decideRequest,copyEndpoint,selectedItems,toggleBulkItem,selectVisibleItems,clearBulkItems,bulkLocation,setBulkLocation,moveSelectedItems,filters,setters}){ return <section className="browseLayout"><aside className="filterPanel"><h2>Find items</h2><div className="searchBox"><Icon name="search"/><input value={filters.query} onChange={(e)=>setters.setQuery(e.target.value)} placeholder="Search name, shelf, owner, category"/></div><label>Person<select value={filters.ownerFilter} onChange={(e)=>setters.setOwnerFilter(e.target.value)}><option value="all">Everyone</option>{state.users.map((u)=><option key={u.id} value={u.id}>{u.displayName}</option>)}</select></label><label>Floor<select value={filters.floorFilter} onChange={(e)=>setters.setFloorFilter(e.target.value)}><option value="all">All floors</option>{state.floors.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Shelf<select value={filters.shelfFilter} onChange={(e)=>setters.setShelfFilter(e.target.value)}><option value="all">All shelves</option>{state.shelves.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Level<select value={filters.levelFilter} onChange={(e)=>setters.setLevelFilter(e.target.value)}><option value="all">All levels</option>{state.levels.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Season<select value={filters.seasonFilter} onChange={(e)=>setters.setSeasonFilter(e.target.value)}><option value="all">All seasons</option>{state.seasons.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Category<select value={filters.categoryFilter} onChange={(e)=>setters.setCategoryFilter(e.target.value)}><option value="all">All categories</option>{state.categories.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></aside><section className="itemList"><div className="panelHeader"><div><h2>{filtered.length} matching items</h2><p>Locked/private items respect each user profile.</p></div></div><div className="bulkMovePanel"><div><strong>Mass move</strong><span>{selectedItems.length} selected</span></div><div className="bulkActions"><button className="secondaryButton" onClick={selectVisibleItems}>Select all visible</button><button className="secondaryButton" onClick={clearBulkItems}>Clear</button></div><div className="bulkMoveGrid"><label>Floor<select value={bulkLocation.floorId} onChange={(e)=>setBulkLocation({...bulkLocation,floorId:e.target.value})}><option value="">Keep floor</option>{state.floors.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Shelf<select value={bulkLocation.shelfId} onChange={(e)=>setBulkLocation({...bulkLocation,shelfId:e.target.value})}><option value="">Keep shelf</option>{state.shelves.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Level<select value={bulkLocation.levelId} onChange={(e)=>setBulkLocation({...bulkLocation,levelId:e.target.value})}><option value="">Keep level</option>{state.levels.map((x)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><button className="primaryButton" onClick={moveSelectedItems}>Move selected</button></div></div>{filtered.map((item)=><article key={item.id} className={`itemCard ${selected?.id===item.id?'selected':''}`} style={{'--item':itemColor(item,state)}} onClick={()=>setSelectedId(item.id)}><label className="selectBox" onClick={(e)=>e.stopPropagation()}><input type="checkbox" checked={selectedItems.includes(item.id)} onChange={()=>toggleBulkItem(item.id)}/><span>Select</span></label><PhotoBox src={item.photo} label="Item"/><div><span className="tagChip">{item.tag}</span>{item.locked&&<span className="lockChip"><Icon name="lock"/> Locked</span>}<h3>{item.title}</h3><p><Dot color={itemColor(item,state)}/> {userName(state.users,item.ownerId)} · {byId(state.categories,item.categoryId).name} · {byId(state.seasons,item.seasonId).name}</p><button onClick={(e)=>{e.stopPropagation();setters.setFloorFilter(item.location.floorId);setters.setShelfFilter(item.location.shelfId);setters.setLevelFilter(item.location.levelId);}}>{locationLine(item.location,state)}</button></div><span className={`status ${item.status.toLowerCase()}`}>{item.status}</span></article>)}</section>{selected&&<aside className="detailPanel" style={{'--item':itemColor(selected,state)}}><p className="eyebrow">Selected item</p><h2>{selected.title}</h2><div className="scanGrid"><PhotoBox src={selected.photo} label="Item photo"/><PhotoBox src={selected.location.photo} label="Shelf photo"/></div><p>{selected.content}</p><div className="locationCard"><strong>Location</strong><span>{locationLine(selected.location,state)}</span><small>{selected.location.containerType} · {selected.location.containerName||'No container'} · {selected.location.boxSpot||'No spot'}</small></div>{selected.locked&&selected.ownerId!==currentProfile.id&&<div className="requestBox"><strong>Locked by {userName(state.users,selected.ownerId)}</strong><p>Ask before taking this item out.</p><button className="secondaryButton" onClick={()=>requestItem(selected)}>Request to take out</button></div>}{selected.ownerId===currentProfile.id&&selected.requests?.filter((r)=>r.status==='pending').map((r)=><div className="requestBox" key={r.id}><strong>{r.userName} wants this item</strong><p>{r.note}</p><div className="saveRow"><button className="primaryButton" onClick={()=>decideRequest(selected,r,'approved')}>Approve</button><button className="dangerButton" onClick={()=>decideRequest(selected,r,'denied')}>Deny</button></div></div>)}<div className="historyBox"><strong>Latest notes</strong>{(selected.history||[]).slice(0,3).map((h,i)=><small key={i}>{h.date} · {h.person} · {h.action}: {h.note||'No note'}</small>)}</div><div className="saveRow"><button className="primaryButton" onClick={()=>startEdit(selected)}>Edit</button><button className="secondaryButton" onClick={()=>copyEndpoint(selected)}>Copy NFC URL</button><button className="secondaryButton" disabled={selected.locked&&!canTake(selected,currentProfile)} onClick={()=>changeStatus(selected)}>{selected.locked&&!canTake(selected,currentProfile)?'Approval needed':`Mark ${selected.status==='In'?'Out':'In'}`}</button></div></aside>}</section>; }
function ListManager({title,type,list,addTag,newTag,setNewTag,deleteListEntry,updateListEntry,editing}){ return <section className="manager"><h3>{title}</h3>{!editing&&<div className="viewChips">{list.map((e)=><span key={e.id}><Dot color={e.color}/>{e.name}</span>)}</div>}{editing&&<>{list.map((e)=><div className="manageRow" key={e.id}><input value={e.name} onChange={(ev)=>updateListEntry(type,e.id,{name:ev.target.value})}/><input type="color" value={e.color||'#66716b'} onChange={(ev)=>updateListEntry(type,e.id,{color:ev.target.value})}/><button className="textDanger" onClick={()=>deleteListEntry(type,e.id)}>Delete</button></div>)}<div className="inlineForm"><input placeholder={`New ${type}`} value={newTag.type===type?newTag.name:''} onChange={(e)=>setNewTag({type,name:e.target.value,color:newTag.color||palette[0]})}/><input type="color" value={newTag.type===type?newTag.color:palette[0]} onChange={(e)=>setNewTag({...newTag,type,color:e.target.value})}/><button className="primaryButton" onClick={addTag}>Add</button></div></>}</section>; }
function LocationsTab({groups,state,quickFilter,startEdit,addTag,newTag,setNewTag,deleteListEntry,updateListEntry,editing,setEditing}){ return <section className="wideStack"><div className="panelHeader safeHeader"><div><h2>Shelves and floors</h2><p>Viewing is safe. Tap Edit before changing names, colors, or deleting.</p></div><button className={editing?'dangerButton':'secondaryButton'} onClick={()=>setEditing(!editing)}>{editing?'Done editing':'Edit shelves'}</button></div><div className="managerGrid"><ListManager title="Floors / Rooms" type="floor" list={state.floors} addTag={addTag} newTag={newTag} setNewTag={setNewTag} deleteListEntry={deleteListEntry} updateListEntry={updateListEntry} editing={editing}/><ListManager title="Shelves" type="shelf" list={state.shelves} addTag={addTag} newTag={newTag} setNewTag={setNewTag} deleteListEntry={deleteListEntry} updateListEntry={updateListEntry} editing={editing}/><ListManager title="Shelf Levels" type="level" list={state.levels} addTag={addTag} newTag={newTag} setNewTag={setNewTag} deleteListEntry={deleteListEntry} updateListEntry={updateListEntry} editing={editing}/></div><div className="locationsGrid">{groups.map((g)=><article key={g.key} className="locationTile"><PhotoBox src={g.location.photo} label="Shelf photo"/><div className="locationTileBody"><h2>{locationLine(g.location,state)}</h2><p>{g.items.length} items</p><div className="miniList">{g.items.map((item)=><button key={item.id} onClick={()=>startEdit(item)}><span><Dot color={itemColor(item,state)}/> {item.title}</span><small>{userName(state.users,item.ownerId)} · {byId(state.categories,item.categoryId).name}</small></button>)}</div><button className="secondaryButton" onClick={()=>quickFilter({floorFilter:g.location.floorId,shelfFilter:g.location.shelfId,levelFilter:g.location.levelId,ownerFilter:'all'})}>Show everyone here</button></div></article>)}</div></section>; }
function TagsTab({state,quickFilter,addTag,newTag,setNewTag,deleteListEntry,updateListEntry,editing,setEditing}){ return <section className="wideStack"><div className="panelHeader safeHeader"><div><h2>Categories and seasonal tags</h2><p>Viewing is safe. Tap Edit before changing names, colors, or deleting.</p></div><button className={editing?'dangerButton':'secondaryButton'} onClick={()=>setEditing(!editing)}>{editing?'Done editing':'Edit tags'}</button></div><div className="managerGrid"><ListManager title="Categories" type="category" list={state.categories} addTag={addTag} newTag={newTag} setNewTag={setNewTag} deleteListEntry={deleteListEntry} updateListEntry={updateListEntry} editing={editing}/><ListManager title="Seasonal / Holiday Tags" type="season" list={state.seasons} addTag={addTag} newTag={newTag} setNewTag={setNewTag} deleteListEntry={deleteListEntry} updateListEntry={updateListEntry} editing={editing}/></div><div className="categoryCards">{[...state.categories.map((x)=>({...x,type:'category'})),...state.seasons.map((x)=>({...x,type:'season'}))].map((tag)=><article key={`${tag.type}-${tag.id}`} style={{'--item':tag.color}}><h3><Dot color={tag.color}/> {tag.name}</h3><p>{state.items.filter((i)=>tag.type==='category'?i.categoryId===tag.id:i.seasonId===tag.id).length} items</p><button className="secondaryButton" onClick={()=>quickFilter(tag.type==='category'?{categoryFilter:tag.id}:{seasonFilter:tag.id})}>View items</button></article>)}</div></section>; }
function MySettings({currentProfile,updateCurrentUser,readPhoto,installApp,reopenGuide,backups,refreshBackups,rollbackBackup,schemeList}){ const [pin,setPin]=useState(''),[verify,setVerify]=useState(''); const changePin=()=>{ if(!/^\d{4}$/.test(pin)||pin!==verify) return; updateCurrentUser({pin,pinSet:true},'PIN changed'); setPin(''); setVerify(''); }; const isAndrew=currentProfile.id==='andrew'; return <section className="settingsPanel"><article className="personCard solo"><Avatar user={currentProfile}/><h2>My Settings</h2><p>Only {currentProfile.displayName}'s settings are editable while logged in. Andrew also gets inventory rollback controls.</p><label>Name<input value={currentProfile.displayName} onChange={(e)=>updateCurrentUser({displayName:e.target.value})}/></label><label>Profile note<input value={currentProfile.helperText||''} onChange={(e)=>updateCurrentUser({helperText:e.target.value})}/></label><div className="fieldGrid"><label>My color<input type="color" value={currentProfile.accent||'#16766f'} onChange={(e)=>updateCurrentUser({accent:e.target.value})}/></label><label>Light / dark mode<select value={currentProfile.mode||'light'} onChange={(e)=>updateCurrentUser({mode:e.target.value})}><option value="light">Light</option><option value="dark">Dark</option></select></label></div><div className="fieldGrid"><label>App theme<select value={currentProfile.theme||'summer'} onChange={(e)=>updateCurrentUser({theme:e.target.value,scheme:(themeSchemes[e.target.value]||[])[0]?.[0]})}>{themes.map((t)=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label>Color scheme<select value={currentProfile.scheme||schemeList?.[0]?.[0]||'default'} onChange={(e)=>updateCurrentUser({scheme:e.target.value})}>{(schemeList||[]).map((x)=><option key={x[0]} value={x[0]}>{titleCase(x[0])}</option>)}</select></label></div><label>Photo<input type="file" accept="image/*" capture="environment" onChange={(e)=>readPhoto(e.target.files?.[0],(photo)=>updateCurrentUser({photo}))}/><small>On phones this opens the camera; on PCs it uploads an image.</small></label><button className="primaryButton wide" onClick={installApp}>Add to Home Screen</button><button className="secondaryButton wide" onClick={reopenGuide}>Reopen setup guide</button><div className="guideBox"><strong>Quick guide</strong><small>Home shows counts and shortcuts. Add Item saves an NFC item with item, shelf, box and location photos. Browse finds items, bulk-moves selected items, and handles locked item requests. Shelves shows shelf/level groups. Tags manages category and seasonal colors. NFC routes include /tag/001, /shelf/001, /shelf/001/mid, and /box/023.</small></div>{isAndrew&&<div className="rollbackBox"><div className="panelHeader"><div><h3>Inventory rollback</h3><p>Cloud saves keep the 5 latest snapshots. Restore one if a phone or PC save goes sideways.</p></div><button className="secondaryButton" onClick={refreshBackups}>Refresh saves</button></div>{backups.length===0&&<small>No backup list loaded yet.</small>}{backups.map((b)=><div className="backupRow" key={b.id}><span><strong>{new Date(b.createdAt).toLocaleString()}</strong><small>{b.reason} · {b.itemCount} items</small></span><button className="dangerButton" onClick={()=>window.confirm('Restore this inventory snapshot?')&&rollbackBackup(b.id)}>Restore</button></div>)}</div>}<div className="pinSetup"><label>New PIN<input inputMode="numeric" maxLength="4" value={pin} onChange={(e)=>setPin(e.target.value.replace(/\D/g,'').slice(0,4))}/></label><label>Verify PIN<input inputMode="numeric" maxLength="4" value={verify} onChange={(e)=>setVerify(e.target.value.replace(/\D/g,'').slice(0,4))}/></label></div><button className="secondaryButton wide" disabled={!/^\d{4}$/.test(pin)||pin!==verify} onClick={changePin}>Save PIN</button></article></section>; }

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));
}

createRoot(document.getElementById('root')).render(<App />);
